message.content:
{
  "title": "The Ember Crown Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A distress letter arrives at the scouts' camp.",
      "visual_description": "A windswept hill camp at dawn, a hawk delivering a sealed scroll to a cloaked ranger beside a flickering campfire, ruined city spires visible on the horizon.",
      "characters": ["Captain Iselle", "Brann the Ranger"]
    },
    {
      "scene_number": 2,
      "caption": "The rescue party gathers and studies an old map.",
      "visual_description": "Four figures crouched around a parchment map weighed down with stones, lantern light catching their faces, the ruined city sketched in faded ink.",
      "characters": ["Captain Iselle", "Brann the Ranger", "Mira the Mage", "Oswin the Steward"]
    },
    {
      "scene_number": 3,
      "caption": "They approach the broken castle gates at dusk.",
      "visual_description": "Two enormous iron-bound gates split down the middle, vines crawling across heraldic carvings, the party silhouetted against a violet twilight sky.",
      "characters": ["Captain Iselle", "Brann the Ranger", "Mira the Mage", "Oswin the Steward"]
    },
    {
      "scene_number": 4,
      "caption": "A frightened townsperson warns them of patrols.",
      "visual_description": "A trembling woman in a patched shawl pulling Iselle into a doorway, broken cobblestones underfoot, smoke curling from a distant rooftop.",
      "characters": ["Captain Iselle", "Hesta the Baker"]
    },
    {
      "scene_number": 5,
      "caption": "Armored patrols march past their hiding place.",
      "visual_description": "A column of black-plated soldiers with crimson sashes tramping through a narrow alley, the party pressed flat behind a collapsed market stall.",
      "characters": ["Brann the Ranger", "Mira the Mage", "Oswin the Steward", "Captain Iselle"]
    },
    {
      "scene_number": 6,
      "caption": "Tattered royal banners reveal whose city this once was.",
      "visual_description": "A wide plaza with torn gold-and-blue banners hanging from broken poles, a cracked statue of a king missing its crown, dust motes in slanted light.",
      "characters": ["Oswin the Steward", "Captain Iselle"]
    },
    {
      "scene_number": 7,
      "caption": "Oswin recognizes the captured noble from a banner crest.",
      "visual_description": "Oswin holding up a torn banner with a phoenix sigil, eyes wide with recognition, his lantern casting long shadows on the rubble around him.",
      "characters": ["Oswin the Steward", "Mira the Mage"]
    },
    {
      "scene_number": 8,
      "caption": "Brann scouts ahead toward the cursed tower.",
      "visual_description": "Brann perched on a crumbling rooftop, spyglass aimed at a tall blackened tower wreathed in greenish mist, ravens circling its peak.",
      "characters": ["Brann the Ranger"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a sleeping dragon reach them through whispers.",
      "visual_description": "A cluster of huddled refugees by a broken fountain pointing fearfully toward a far mountain, scales glinting in the carved stone of the fountain itself.",
      "characters": ["Hesta the Baker", "Captain Iselle", "Mira the Mage"]
    },
    {
      "scene_number": 10,
      "caption": "Mira deciphers the runes on a sealed magic door.",
      "visual_description": "An arched door of pale stone carved with glowing blue runes, Mira's fingertips trailing light across the symbols, the others watching in tense silence.",
      "characters": ["Mira the Mage", "Captain Iselle", "Oswin the Steward"]
    },
    {
      "scene_number": 11,
      "caption": "The door opens onto a spiraling stair into the tower.",
      "visual_description": "A dark stairwell winding upward into shadow, faint motes of green light drifting like fireflies, the party stepping cautiously inside.",
      "characters": ["Captain Iselle", "Mira the Mage", "Brann the Ranger", "Oswin the Steward"]
    },
    {
      "scene_number": 12,
      "caption": "They find Princess Elen chained in a high chamber.",
      "visual_description": "A round tower room with a tall arched window, a young woman in a torn gown chained to a stone pillar, moonlight pooling around her bare feet.",
      "characters": ["Princess Elen", "Captain Iselle", "Mira the Mage"]
    },
    {
      "scene_number": 13,
      "caption": "Mira breaks the binding spell with a flash of silver light.",
      "visual_description": "Chains shattering into glowing fragments mid-air, Mira's staff blazing with cold light, Princess Elen shielding her eyes as Iselle catches her.",
      "characters": ["Mira the Mage", "Princess Elen", "Captain Iselle"]
    },
    {
      "scene_number": 14,
      "caption": "Alarm horns sound across the ruined city.",
      "visual_description": "View from the tower window: torches flaring to life along distant walls, dark shapes of patrols converging, Brann pointing urgently down a side stair.",
      "characters": ["Brann the Ranger", "Captain Iselle", "Princess Elen"]
    },
    {
      "scene_number": 15,
      "caption": "Oswin stumbles into a trap and is nearly caught.",
      "visual_description": "Oswin tangled in a falling net of dark cord in a narrow corridor, Brann leaping in with a curved knife to cut him free, sparks from a wall sconce.",
      "characters": ["Oswin the Steward", "Brann the Ranger"]
    },
    {
      "scene_number": 16,
      "caption": "They flee through the burning lower courtyards.",
      "visual_description": "The party sprinting past collapsed colonnades, embers raining down, a fallen banner smoldering underfoot, Iselle pulling Elen by the hand.",
      "characters": ["Captain Iselle", "Princess Elen", "Mira the Mage", "Brann the Ranger", "Oswin the Steward"]
    },
    {
      "scene_number": 17,
      "caption": "The final escape begins across the cracked stone bridge.",
      "visual_description": "A long, narrow bridge over a fog-filled chasm, stones crumbling behind them as they run, torches of pursuers visible at the bridge's far end of the city.",
      "characters": ["Captain Iselle", "Princess Elen", "Mira the Mage", "Brann the Ranger", "Oswin the Steward"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, they look back at the fallen city.",
      "visual_description": "Five figures standing on a grassy ridge at sunrise, the ruined city smoking in the valley behind them, Princess Elen wrapped in Iselle's cloak.",
      "characters": ["Captain Iselle", "Princess Elen", "Mira the Mage", "Brann the Ranger", "Oswin the Steward"]
    }
  ]
}

